  q(SCIENCES,'Histoire des sciences','Quelle association relie correctement Copernic et Galilée à l’astronomie ?','Copernic — modèle héliocentrique ; Galilée — astronomie télescopique',['Copernic — pénicilline ; Galilée — tableau périodique','Copernic — sélection naturelle ; Galilée — vaccination','Copernic — radioactivité ; Galilée — World Wide Web'],'Copernic place le Soleil au centre du modèle planétaire ; Galilée apporte des observations télescopiques majeures.');
  q(SCIENCES,'Histoire des sciences','Quelle série associe correctement trois figures de la physique à leur domaine ?','Marie Curie — radioactivité ; Einstein — relativité ; Tesla — courant alternatif',['Marie Curie — évolution ; Einstein — vaccination ; Tesla — pénicilline','Marie Curie — tectonique ; Einstein — tableau périodique ; Tesla — génétique','Marie Curie — Internet ; Einstein — pasteurisation ; Tesla — héliocentrisme'],'Ces associations relient trois figures majeures à leur domaine scientifique principal.');

  q(SCIENCES,'Évolution','À quelle théorie Charles Darwin est-il principalement associé ?','L’évolution par sélection naturelle',['La relativité générale','La théorie cellulaire','La tectonique des plaques'],'Darwin explique l’évolution des populations par des variations héréditaires et des différences de reproduction.');
  q(SCIENCES,'Évolution','Pourquoi est-il incorrect de dire que l’évolution poursuit un but prévu à l’avance ?','La sélection agit sur des variations présentes sans objectif prédéterminé',['Toutes les espèces sont immuables','Chaque individu choisit ses mutations utiles','L’environnement ne joue aucun rôle'],'L’évolution n’est pas un projet orienté vers une forme supposée parfaite.');
  q(SCIENCES,'Biodiversité','Quels trois niveaux la biodiversité englobe-t-elle ?','Diversité des gènes, des espèces et des écosystèmes',['Diversité des atomes, des planètes et des galaxies','Diversité des muscles, des os et des organes seulement','Diversité des climats uniquement'],'La biodiversité s’observe au sein des espèces, entre les espèces et entre les milieux.');
  q(SCIENCES,'Écologie','Qu’est-ce qu’un écosystème ?','Un milieu et les êtres vivants qui y interagissent',['Une seule population isolée de son milieu','Une liste d’espèces sans relations','Uniquement la partie minérale d’un paysage'],'Un écosystème associe un biotope et une communauté d’êtres vivants en interaction.');
  q(SCIENCES,'Écologie','Qu’est-ce que la canopée ?','La strate supérieure d’une forêt formée par les couronnes des arbres',['La couche la plus profonde du sol','Le réseau souterrain de racines uniquement','Une zone dépourvue de végétation'],'La canopée reçoit directement la lumière et abrite de nombreux organismes.');
